import assert from 'node:assert/strict'
import test from 'node:test'
import { dirname, join } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'
import { writeFileSync, unlinkSync } from 'node:fs'

import esbuild from 'esbuild'

const here = dirname(fileURLToPath(import.meta.url))
const bundlePath = join(here, '.tmp-pdf-dest.mjs')

// The worker module is generated by build.mjs; tests must not depend on a
// previous build, so it is stubbed out at bundle time.
const stubWorker = {
  name: 'stub-worker',
  setup(build) {
    build.onResolve({ filter: /generated\/pdf-worker\.js$/ }, () => ({
      path: 'pdf-worker-stub',
      namespace: 'stub',
    }))
    build.onLoad({ filter: /.*/, namespace: 'stub' }, () => ({
      contents: 'export const PDF_WORKER_TEXT = ""',
      loader: 'js',
    }))
  },
}

const result = await esbuild.build({
  stdin: {
    contents: `export { destinationToPage, pageIndexOfDestination } from '../src/client/formats/pdf.js'`,
    resolveDir: here,
    sourcefile: 'pdf-dest-entry.js',
    loader: 'js',
  },
  bundle: true,
  write: false,
  format: 'esm',
  platform: 'browser',
  plugins: [stubWorker],
  logLevel: 'silent',
})
writeFileSync(bundlePath, result.outputFiles[0].text)
const { destinationToPage, pageIndexOfDestination } = await import(pathToFileURL(bundlePath).href)

function fakeDoc(options = {}) {
  return {
    getDestination: options.getDestination ?? (async () => null),
    getPageIndex: options.getPageIndex ?? (async () => 0),
  }
}

test('resolves numeric and reference destinations', async () => {
  try {
    assert.equal(await pageIndexOfDestination(fakeDoc(), 4), 5)
    assert.equal(
      await pageIndexOfDestination(
        fakeDoc({ getPageIndex: async (ref) => (ref.num === 3 ? 9 : 0) }),
        [{ num: 3, gen: 0 }],
      ),
      10,
    )
  } finally {
    try {
      unlinkSync(bundlePath)
    } catch {
      // best effort cleanup
    }
  }
})

test('resolves named destinations through the async pdf.js API', async () => {
  const doc = fakeDoc({
    getDestination: async (name) => (name === 'chapter-2' ? [{ num: 4, gen: 0 }] : null),
    getPageIndex: async (ref) => (ref.num === 4 ? 12 : 0),
  })
  assert.deepEqual(await destinationToPage(doc, 'chapter-2'), [{ num: 4, gen: 0 }])
  assert.equal(await pageIndexOfDestination(doc, 'chapter-2'), 13)
  assert.equal(await pageIndexOfDestination(doc, 'missing'), null)
})

test('unresolvable or broken destinations resolve to null instead of throwing', async () => {
  assert.equal(await destinationToPage(fakeDoc(), null), null)
  assert.equal(await pageIndexOfDestination(fakeDoc(), undefined), null)
  assert.equal(await pageIndexOfDestination(fakeDoc({ getPageIndex: async () => { throw new Error('bad') } }), [{ num: 9, gen: 0 }]), null)
  assert.equal(await pageIndexOfDestination(fakeDoc(), []), null)
})
